+type Version = [bigint, bigint, bigint];
+type Part = bigint | null;
+type Partial = [Part, Part, Part];
+type Predicate = (v: Version) => boolean;
+
+const VERSION_RE = /^(\d+)\.(\d+)\.(\d+)$/;
+const NUMBER_RE = /^\d+$/;
+const WILDCARD_RE = /^[xX*]$/;
+const COMPARATOR_RE = /^(>=|<=|>|<|=|~|\^)?(.*)$/;
+
+function parseVersion(text: string): Version {
+  const match = VERSION_RE.exec(text);
+  if (!match) throw new Error(`Invalid version: ${text}`);
+  return [BigInt(match[1]), BigInt(match[2]), BigInt(match[3])];
+}
+
+function parsePartial(text: string): Partial {
+  const pieces = text.split(".");
+  if (pieces.length > 3) throw new Error(`Invalid version: ${text}`);
+  const parts: Partial = [null, null, null];
+  let wildcard = false;
+  pieces.forEach((piece, i) => {
+    if (WILDCARD_RE.test(piece)) {
+      wildcard = true;
+    } else if (NUMBER_RE.test(piece) && !wildcard) {
+      parts[i] = BigInt(piece);
+    } else {
+      throw new Error(`Invalid version: ${text}`);
+    }
+  });
+  return parts;
+}
+
+function compare(a: Version, b: Version): number {
+  for (let i = 0; i < 3; i++) {
+    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
+  }
+  return 0;
+}
+
+/** The partial version with missing numbers filled with zeros, e.g. `1.2` -> 1.2.0. */
+function lowerBound(parts: Partial): Version {
+  return [parts[0]!, parts[1] ?? 0n, parts[2] ?? 0n];
+}
